<?php
namespace App\Http\Controllers;use App\Models\{ExtraDuty,Employee,Project};use Illuminate\Http\Request;class ExtraDutyController extends Controller{function index(){return view('crud.index',['title'=>'Extra Duties','items'=>ExtraDuty::with('employee','project')->latest()->paginate(30),'type'=>'extra-duties']);}function create(){return view('duties.form',['item'=>new ExtraDuty,'employees'=>Employee::all(),'projects'=>Project::all()]);}function store(Request $r){$d=$r->validate(['employee_id'=>'required','project_id'=>'nullable','duty_date'=>'required|date','day_type'=>'required','hours_worked'=>'required|numeric','rate'=>'required|numeric','remarks'=>'nullable']);$d['amount']=$d['hours_worked']*$d['rate'];ExtraDuty::create($d+['approval_status'=>'pending']);return redirect()->route('extra-duties.index')->with('success','Saved');}function show(ExtraDuty $extraDuty){return view('crud.show',['item'=>$extraDuty]);}function edit(ExtraDuty $extraDuty){return view('duties.form',['item'=>$extraDuty,'employees'=>Employee::all(),'projects'=>Project::all()]);}function update(Request $r,ExtraDuty $extraDuty){$d=$r->all();$d['amount']=($d['hours_worked']??$extraDuty->hours_worked)*($d['rate']??$extraDuty->rate);$extraDuty->update($d);return redirect()->route('extra-duties.index');}function destroy(ExtraDuty $extraDuty){$extraDuty->delete();return back();}function approve(ExtraDuty $extraDuty){$extraDuty->update(['approval_status'=>'approved','approved_by'=>auth()->id(),'approved_at'=>now(),'amount'=>$extraDuty->hours_worked*$extraDuty->rate]);return back();}function reject(ExtraDuty $extraDuty){$extraDuty->update(['approval_status'=>'rejected']);return back();}}
